package com.joseantonio.reconciliation.domain.model;

import java.time.Instant;

/**
 * An audit alert generated by a batch. A ledger movement raises each rule at most once in its whole life, whatever
 * the number of batches that touch it ({@code ledgerTxId} + rule is the natural key).
 */
public record AuditAlert(
        long batchId,
        Long ledgerTxId,
        ReferenceCode reference,
        String rule,
        Severity severity,
        String description,
        Instant createdAt) {
}
